FVector UEVector(const HPFlight::Vec& V){return FVector(-V[2],V[0],V[1]);}
HPFlight::Vec Cross(const HPFlight::Vec& A,const HPFlight::Vec& B){return {A[1]*B[2]-A[2]*B[1],A[2]*B[0]-A[0]*B[2],A[0]*B[1]-A[1]*B[0]};}
