void AShipManager::OnTerrainContact(const HPPlanet::Contact& Contact){auto* E=Expedition();if(!E)return;Thrust=0;E->Thrust=0;if(Contact.soft){bLanded=true;LandedPlanet=Contact.planet;E->State.message="Touchdown. Open the stern pressure airlock to explore.";E->Save();}else{Venting[3]=true;E->State.message="Hard terrain contact. Repair, level to the local horizon and touch down below 12 m/s.";}}
void AShipManager::LaunchFromSurface(){auto* E=Expedition();if(!E||!bLanded||!bPilot||HabitatsInterlocked()||OuterAirlock->HasOpenGap()||InnerAirlock->HasOpenGap())return;const auto W=HPPlanet::nearest(E->State);for(int K=0;K<3;++K)E->State.velocity[K]=W.n[K]*.008;bLanded=false;LandedPlanet=-1;E->State.autopilot=false;E->State.message="Landing clamps released. Manual thrusters control takeoff.";if(auto* P=Cast<AHeliopauseCharacter>(UGameplayStatics::GetPlayerPawn(this,0));P&&P->IsTabletOpen())P->ToggleTablet();}
void AShipManager::BuildAirlock(){InnerAirlock=GetWorld()->SpawnActor<AHandprintDoor>(FVector(-4200,0,0),FRotator::ZeroRotator);OuterAirlock=GetWorld()->SpawnActor<AHandprintDoor>(FVector(-4500,0,0),FRotator::ZeroRotator);InnerAirlock->DoorName=TEXT("STERN INNER AIRLOCK");OuterAirlock->DoorName=TEXT("EXTERIOR HATCH");InnerAirlock->RoomA=InnerAirlock->RoomB=OuterAirlock->RoomA=OuterAirlock->RoomB=3;Doors.Add(InnerAirlock);Doors.Add(OuterAirlock);for(int Side:{-1,1})Box(GetRootComponent(),FVector(-4350,Side*130,150),FVector(320,20,300),FLinearColor(.23,.4,.39),true);Box(GetRootComponent(),FVector(-4350,0,-10),FVector(320,280,20),FLinearColor(.3,.36,.3),true);Box(GetRootComponent(),FVector(-4350,0,310),FVector(320,280,20),FLinearColor(.3,.36,.3),true);Box(GetRootComponent(),FVector(-4640,0,-20),FVector(280,240,20),FLinearColor(.3,.36,.3),true);}
void AShipManager::TickPlanetaryWorld(){auto* E=Expedition();if(!E)return;const auto& S=E->State;const auto W=HPPlanet::nearest(S);if(OuterAirlock){OuterAirlock->bDeploymentLock=(!bLanded&&S.docked<0)||InnerAirlock->HasOpenGap();InnerAirlock->bDeploymentLock=OuterAirlock->HasOpenGap();}
 if(auto* P=UGameplayStatics::GetPlayerPawn(this,0)){bOutsideShip=bLanded&&P->GetActorLocation().X< -4520;}
 if(W.planet<0||W.planet==13||W.altitude>18000||S.onStation){if(TerrainPatch){TerrainPatch->DestroyComponent();TerrainPatch=nullptr;}TerrainPlanet=-1;return;}
 const auto& Site=HelioExplore::Sites[W.planet];const bool Rebuild=!TerrainPatch||TerrainPlanet!=W.planet||HPPlanet::length(HelioExplore::minus(W.n,TerrainAnchor))*W.radius>35;
 if(Rebuild){TerrainAnchor=W.n;TerrainPlanet=W.planet;auto East=HPPlanet::unit(Cross({0,1,0},TerrainAnchor));if(HPPlanet::length(East)<.5)East={1,0,0};const auto South=HPPlanet::unit(Cross(East,TerrainAnchor));TArray<FVector> V,N;TArray<int32> I;TArray<FVector2D> UV;constexpr int Steps=96;const double Width=4096;
 for(int Z=0;Z<=Steps;++Z)for(int X=0;X<=Steps;++X){HPFlight::Vec P{};for(int K=0;K<3;++K)P[K]=TerrainAnchor[K]*W.radius+East[K]*(double(X)/Steps-.5)*Width+South[K]*(double(Z)/Steps-.5)*Width;const auto Normal=HPPlanet::unit(P);const double H=std::max(0.,HPPlanet::height(W.planet,Normal));for(int K=0;K<3;++K)P[K]=Normal[K]*(W.radius+H)-TerrainAnchor[K]*W.radius;V.Add(UEVector(P)*100);N.Add(UEVector(Normal));UV.Add(FVector2D(std::atan2(Normal[2],Normal[0])/(2*PI)+.5,.5-std::asin(Normal[1])/PI));}
 for(int Z=0;Z<Steps;++Z)for(int X=0;X<Steps;++X){const int A=Z*(Steps+1)+X,B=A+Steps+1;I.Append({A,B,A+1,A+1,B,B+1});}
 if(!TerrainPatch){TerrainPatch=NewObject<UProceduralMeshComponent>(this);TerrainPatch->SetupAttachment(GetRootComponent());TerrainPatch->bUseAsyncCooking=true;TerrainPatch->RegisterComponent();}TerrainPatch->CreateMeshSection_LinearColor(0,V,I,N,UV,TArray<FLinearColor>(),TArray<FProcMeshTangent>(),true);TerrainPatch->SetCollisionProfileName(TEXT("BlockAll"));
 const TCHAR* Name=(W.planet==7||W.planet==12)?TEXT("moon"):(W.planet==10||W.planet==15||W.planet==16)?TEXT("mars"):TEXT("earth");UMaterialInterface* Material=LoadObject<UMaterialInterface>(nullptr,*FString::Printf(TEXT("/Game/Imported/PlanetMaps/M_%s.M_%s"),Name,Name));TerrainPatch->SetMaterial(0,Material?Material:SurfaceAsset);}
 HPFlight::Vec Anchor{};for(int K=0;K<3;++K)Anchor[K]=Site.position[K]+TerrainAnchor[K]*W.radius/1000-S.position[K];const HPFlight::Quat Inv{-S.orientation[0],-S.orientation[1],-S.orientation[2],S.orientation[3]};const FVector Forward=UEVector(HPFlight::rotate(Inv,{0,0,-1})),Right=UEVector(HPFlight::rotate(Inv,{1,0,0}));const FRotator Rotation=FRotationMatrix::MakeFromXY(Forward,Right).Rotator();TerrainPatch->SetRelativeLocation(UEVector(HPFlight::rotate(Inv,Anchor))*100000);TerrainPatch->SetRelativeRotation(Rotation);TerrainPatch->SetVisibility(true);for(USceneComponent* Root:SiteRoots)Root->SetRelativeRotation(Rotation);
}
